CREATE TABLE IF NOT EXISTS stages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,stage_key VARCHAR(60) NOT NULL,stage_order INT NOT NULL DEFAULT 1,status VARCHAR(30) NOT NULL DEFAULT 'draft',settings_json JSON NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id),INDEX(tournament_id));
CREATE TABLE IF NOT EXISTS groups_competition (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,stage_id BIGINT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,group_order INT NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(stage_id) REFERENCES stages(id));
CREATE TABLE IF NOT EXISTS rounds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,stage_id BIGINT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,round_order INT NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(stage_id) REFERENCES stages(id));
CREATE TABLE IF NOT EXISTS venues (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,address VARCHAR(255) NULL,city VARCHAR(120) NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS matches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,stage_id BIGINT UNSIGNED NULL,group_id BIGINT UNSIGNED NULL,round_id BIGINT UNSIGNED NULL,venue_id BIGINT UNSIGNED NULL,home_team_id BIGINT UNSIGNED NOT NULL,away_team_id BIGINT UNSIGNED NOT NULL,scheduled_at DATETIME NULL,status VARCHAR(40) NOT NULL DEFAULT 'scheduled',home_score INT NULL,away_score INT NULL,home_penalties INT NULL,away_penalties INT NULL,homologated_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(home_team_id) REFERENCES teams(id),FOREIGN KEY(away_team_id) REFERENCES teams(id),INDEX(tournament_id,status),INDEX(scheduled_at));
CREATE TABLE IF NOT EXISTS match_lineups (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,match_id BIGINT UNSIGNED NOT NULL,team_id BIGINT UNSIGNED NOT NULL,person_id BIGINT UNSIGNED NOT NULL,lineup_role VARCHAR(30) NOT NULL DEFAULT 'substitute',shirt_number VARCHAR(10) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(match_id) REFERENCES matches(id),FOREIGN KEY(team_id) REFERENCES teams(id),FOREIGN KEY(person_id) REFERENCES people(id),UNIQUE KEY match_person(match_id,person_id));
CREATE TABLE IF NOT EXISTS match_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,match_id BIGINT UNSIGNED NOT NULL,team_id BIGINT UNSIGNED NULL,person_id BIGINT UNSIGNED NULL,assist_person_id BIGINT UNSIGNED NULL,event_type VARCHAR(40) NOT NULL,minute SMALLINT UNSIGNED NULL,period VARCHAR(20) NULL,metadata_json JSON NULL,is_cancelled TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(match_id) REFERENCES matches(id),FOREIGN KEY(team_id) REFERENCES teams(id),FOREIGN KEY(person_id) REFERENCES people(id),INDEX(match_id,event_type));
CREATE TABLE IF NOT EXISTS match_reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,match_id BIGINT UNSIGNED NOT NULL UNIQUE,state VARCHAR(40) NOT NULL DEFAULT 'draft',referee_notes TEXT NULL,organizer_notes TEXT NULL,submitted_at DATETIME NULL,homologated_at DATETIME NULL,retification_reason TEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(match_id) REFERENCES matches(id));
CREATE TABLE IF NOT EXISTS disciplinary_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,match_id BIGINT UNSIGNED NULL,person_id BIGINT UNSIGNED NOT NULL,record_type VARCHAR(40) NOT NULL,description TEXT NULL,match_count INT NOT NULL DEFAULT 1,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(match_id) REFERENCES matches(id),FOREIGN KEY(person_id) REFERENCES people(id));
CREATE TABLE IF NOT EXISTS suspensions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,person_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(160) NOT NULL,matches_total INT NOT NULL DEFAULT 1,matches_served INT NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'active',generated_by_record_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(person_id) REFERENCES people(id));
CREATE TABLE IF NOT EXISTS standings_snapshots (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,stage_id BIGINT UNSIGNED NULL,group_id BIGINT UNSIGNED NULL,team_id BIGINT UNSIGNED NOT NULL,played INT NOT NULL DEFAULT 0,wins INT NOT NULL DEFAULT 0,draws INT NOT NULL DEFAULT 0,losses INT NOT NULL DEFAULT 0,goals_for INT NOT NULL DEFAULT 0,goals_against INT NOT NULL DEFAULT 0,points INT NOT NULL DEFAULT 0,position INT NULL,calculated_at DATETIME NOT NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(team_id) REFERENCES teams(id),INDEX(tournament_id,group_id,position));
CREATE TABLE IF NOT EXISTS news_posts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,title VARCHAR(220) NOT NULL,slug VARCHAR(240) NOT NULL,excerpt TEXT NULL,body MEDIUMTEXT NOT NULL,cover_path VARCHAR(255) NULL,status VARCHAR(30) NOT NULL DEFAULT 'draft',published_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,created_by BIGINT UNSIGNED NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id),UNIQUE KEY tournament_news_slug(tournament_id,slug));
CREATE TABLE IF NOT EXISTS galleries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,description TEXT NULL,status VARCHAR(30) NOT NULL DEFAULT 'draft',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id));
CREATE TABLE IF NOT EXISTS gallery_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,gallery_id BIGINT UNSIGNED NOT NULL,file_path VARCHAR(255) NOT NULL,caption VARCHAR(220) NULL,sort_order INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(gallery_id) REFERENCES galleries(id));
CREATE TABLE IF NOT EXISTS transfers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,person_id BIGINT UNSIGNED NOT NULL,from_team_id BIGINT UNSIGNED NULL,to_team_id BIGINT UNSIGNED NULL,status VARCHAR(30) NOT NULL DEFAULT 'requested',reason TEXT NULL,requested_at DATETIME NOT NULL,approved_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(person_id) REFERENCES people(id));
CREATE TABLE IF NOT EXISTS documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,file_path VARCHAR(255) NOT NULL,visibility VARCHAR(30) NOT NULL DEFAULT 'private',status VARCHAR(30) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id));
CREATE TABLE IF NOT EXISTS awards (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,title VARCHAR(140) NOT NULL,person_id BIGINT UNSIGNED NULL,team_id BIGINT UNSIGNED NULL,description TEXT NULL,status VARCHAR(30) NOT NULL DEFAULT 'draft',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id));
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,tournament_id BIGINT UNSIGNED NULL,title VARCHAR(180) NOT NULL,body TEXT NOT NULL,read_at DATETIME NULL,created_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(tournament_id) REFERENCES tournaments(id));
CREATE TABLE IF NOT EXISTS export_jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,tournament_id BIGINT UNSIGNED NULL,export_type VARCHAR(60) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'queued',file_path VARCHAR(255) NULL,error_message TEXT NULL,created_at DATETIME NOT NULL,completed_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id));
